Abstract the sharding behind a repository class so callers never see it:

```typescript
const SHARD_COUNT = 10;

class OrderRepository {
  async getRecentOrders(userId: string, days: number): Promise<Order[]> {
    const cutoff = Date.now() - days * 86400_000;

    // Fan out to all shards in parallel
    const shardQueries = Array.from({ length: SHARD_COUNT }, (_, i) =>
      this.queryOneShard(`${userId}#shard${i}`, cutoff)
    );

    const results = await Promise.all(shardQueries);
    return results
      .flat()
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 100);
  }

  private async queryOneShard(shardKey: string, cutoff: number): Promise<Order[]> {
    const result = await this.ddb.query({
      TableName: 'orders',
      IndexName: 'userId-createdAt-index',
      KeyConditionExpression: 'userId = :uid AND createdAt > :cutoff',
      ExpressionAttributeValues: { ':uid': shardKey, ':cutoff': cutoff },
      ScanIndexForward: false,
      Limit: 100,
    }).promise();
    return result.Items as Order[];
  }
}
```

With 10 shards, 10 parallel queries of a warm partition each take ~20-40ms instead of 800ms on a single hot partition.
